contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address receiver, uint amount) public { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(receiver == address(this));
        uint balBefore = address(this).balance;
        bool reverted;
        c.sendTo(receiver, amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        assert(reverted ? address(this).balance == balBefore : address(this).balance == balBefore + amount);
    }

    receive() external payable {}
}

